// Porta de services-layer/src/services/moloni.service.js (versão Express).
function falha(tipo) {
  return [{ json: { ok: false, tipo, estadoHTTP: 502 } }];
}

function classificar(erros) {
  const mensagens = erros
    .map((erro) => String(erro.msg || erro.message || ""))
    .join(" ")
    .toLowerCase();

  if (/must be logged in|unauthorized|unauthenticated|invalid.*token|invalid.*api.key|access denied/i.test(mensagens)) {
    return falha("AUTENTICACAO");
  }
  if (/validation|invalid.*field|required|must be|graphql_validation_failed/i.test(mensagens)) {
    return falha("VALIDACAO");
  }
  return falha("OPERACAO");
}

const resposta = $input.first().json;

// Sem ligação: o pedido HTTP falhou antes de haver resposta.
if (resposta.statusCode === undefined) return falha("COMUNICACAO");
if (resposta.statusCode === 401 || resposta.statusCode === 403) return falha("AUTENTICACAO");
if (resposta.statusCode < 200 || resposta.statusCode >= 300) return falha("HTTP");

let resultado;
try {
  resultado = typeof resposta.body === "string" ? JSON.parse(resposta.body) : resposta.body;
} catch {
  return falha("RESPOSTA_INVALIDA");
}

if (Array.isArray(resultado?.errors) && resultado.errors.length > 0) return classificar(resultado.errors);
if (!resultado?.data || typeof resultado.data !== "object") return falha("RESPOSTA_INVALIDA");

for (const operacao of Object.values(resultado.data)) {
  if (Array.isArray(operacao?.errors) && operacao.errors.length > 0) return classificar(operacao.errors);
}

return [{ json: { ok: true, data: resultado.data } }];
